import{_ as l,l as n,o as e,c as i,v as r,p as s,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"变长记录与溢出页","description":"","frontmatter":{"title":"变长记录与溢出页","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/varlen-overflow.md","filePath":"cs/varlen-overflow.md","lastUpdated":1789023840000}'),h={name:"cs/varlen-overflow.md"};function A(_,a,E,D,f,m){const o=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="变长记录与溢出页" tabindex="-1">变长记录与溢出页 <a class="header-anchor" href="#变长记录与溢出页" aria-label="Permalink to &quot;变长记录与溢出页&quot;">​</a></h1><div class="epigraph"><p>槽化页假定记录进一页；变长列一涨，行要拆成页内头与溢出页链，RID 仍指头，扫描变成追逐。</p><footer>—— 据 Ramakrishnan and Gehrke 页与槽；Gray and Reuter；主干 page-slot 的溢出补全</footer></div><p><a href="/cs/learned-index">上一课</a>在有序键上赌模型。本课不拟合 CDF。缺口是行存物理：主干 <a href="/cs/page-slot">页与槽</a> 给定长直觉；真实 <code>VARCHAR</code>/<code>JSONB</code> 变长，更新变长导致页满、行迁移、溢出页（overflow / TOAST 一类）。延迟物化与覆盖索引都假设 RID 仍能找到载荷。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>插入变长行：页空闲不够则新页或压缩空洞。更新变长：行变大可能迁到另一页，旧槽留转发地址（forwarding RID），索引可仍指旧 RID，避免全改二级索引。极大字段：页内只留指针，数据在溢出页或侧表。缺口是<strong>访问路径变间接</strong>，I/O 从一次变多次，代价模型要计。</p><p>碎片：频繁变长更新留下不可用小洞，需要页内整理或 vacuum。与 pin-latch：迁移时持写闩，读者要跟转发。</p><p><span class="marginnote">PostgreSQL TOAST、InnoDB 溢出页是产品名。本课机制：行头+溢出链。本课不把大对象 API 写完——下一课 BLOB。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>页格式：槽指向行头；行头含标志「有溢出」。扫描：跟指针读列。压缩行（前缀压缩）是另一减少溢出的手段。最大行限制：超过则强制溢出或拒绝。</p><p>索引：键通常截断或哈希前缀，完整键在堆行。比较长键可能要取溢出——执行器注意。</p>',10)),(e(),s(c,null,{default:t(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RID%5B%22RID%20%E6%A7%BD%22%5D%20--%3E%20HEAD%5B%22%E9%A1%B5%E5%86%85%E8%A1%8C%E5%A4%B4%22%5D%0A%20%20HEAD%20--%3E%20IN%5B%22%E9%A1%B5%E5%86%85%E5%88%97%22%5D%0A%20%20HEAD%20--%3E%20OV%5B%22%E6%BA%A2%E5%87%BA%E9%A1%B5%E9%93%BE%22%5D%0A%20%20UPD%5B%22%E8%A1%8C%E5%8F%98%E5%A4%A7%22%5D%20--%3E%20FWD%5B%22%E8%BD%AC%E5%8F%91%20RID%20%E6%88%96%E6%96%B0%E6%A7%BD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>WAL：溢出页与主页都要记生理日志，恢复顺序按 LSN。延迟物化：先读行头谓词列，谓词列若在溢出则迟物化失败变早读。列存较少「一行跨页」，但超长字符串仍有字典块。</p><p>缓冲：溢出页易成一次性，2Q 应快速逐出，避免污染。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 BLOB 流式 API 与外部文件。也不把宽列单元格当溢出链。表分区是水平切，溢出是垂直拆行。</p><p>后课默认：变长更新可能转发与溢出，点查 I/O 不只一页。大对象存储：专门的大值路径，避免普通行槽被单列撑爆。</p><p>转发保持二级索引稳定，代价是每次多一次跳。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>变长行用槽+可选溢出链；更新可转发 RID。</li><li>代价与 WAL 必须看见间接跳。</li><li>大对象存储下一课：超大值不走普通槽。</li><li>出处：Ramakrishnan and Gehrke；Gray and Reuter；TOAST/溢出实践。</li></ul>',9))])}const T=l(h,[["render",A]]);export{B as __pageData,T as default};
